<?php
namespace qqworld_collector\module\settings; use qqworld_collector\lib; use wp_update_image_subsizes; class no_thumbnail_sizes extends lib { public function __construct() { add_filter( 'intermediate_image_sizes_advanced', array($this, 'normal_image_sizes') ); add_filter( 'wp_get_missing_image_subsizes', array($this, 'normal_image_sizes') ); add_action( 'wp_insert_post', array($this, 'wp_insert_post'), 11, 2 ); add_action( 'wp_ajax_qqworld-collector-no-thumbnail-sizes-scanning', array($this, 'scanning') ); add_action( 'wp_ajax_nopriv_qqworld-collector-no-thumbnail-sizes-scanning', array($this, 'scanning') ); add_action( 'wp_ajax_qqworld-collector-no-thumbnail-sizes-restart-scanning', array($this, 'restart_scanning') ); add_action( 'wp_ajax_nopriv_qqworld-collector-no-thumbnail-sizes-restart-scanning', array($this, 'restart_scanning') ); } public function init() { if ( filter_var($this->options->qc_no_thumbnail_sizes_enabled, FILTER_VALIDATE_BOOLEAN) ) { add_filter( 'bulk_actions-upload', array($this, 'add_bulk_actions') ); add_filter( 'handle_bulk_actions-upload', array($this, 'handle_bulk_actions'), 10, 3 ); add_action( 'qqworld-collector-admin-notices-upload', array($this, 'admin_notices') ); } } public function normal_image_sizes($sizes) { if ( filter_var($this->options->qc_no_thumbnail_sizes_enabled, FILTER_VALIDATE_BOOLEAN) && !empty($this->options->qc_no_thumbnail_sizes_size) ) { foreach ($this->options->qc_no_thumbnail_sizes_size as $size) { if (isset($sizes[$size])) unset($sizes[$size]); } } return $sizes; } public function featured_image_sizes($sizes) { if ( filter_var($this->options->qc_no_thumbnail_sizes_enabled, FILTER_VALIDATE_BOOLEAN) && !empty($this->options->qc_no_thumbnail_sizes_featured_image_size) ) { foreach ($this->options->qc_no_thumbnail_sizes_featured_image_size as $size) { if (isset($sizes[$size])) unset($sizes[$size]); } } return $sizes; } public function wp_insert_post($post_ID, $post = null) { if (isset($post) && in_array($post->post_status, array('auto-draft', 'inherit'))) return; if ( !filter_var($this->options->qc_no_thumbnail_sizes_enabled, FILTER_VALIDATE_BOOLEAN) || empty($this->options->qc_no_thumbnail_sizes_featured_image_size) ) return; $attachment_id = get_post_thumbnail_id($post_ID); if ($attachment_id) $this->update_featured_image_subsizes($attachment_id); } public function update_normal_image_subsizes($attachment_id) { if ( !filter_var($this->options->qc_no_thumbnail_sizes_enabled, FILTER_VALIDATE_BOOLEAN) || empty($this->options->qc_no_thumbnail_sizes_size) ) return; add_filter( 'qqworld-collector-disable-watermark', '__return_true' ); $metadata = wp_get_attachment_metadata($attachment_id); $metadata = $this->delete_subsizes($attachment_id, $metadata, $this->options->qc_no_thumbnail_sizes_size); if (!function_exists('\wp_update_image_subsizes')) include ABSPATH . DIRECTORY_SEPARATOR . 'wp-admin' . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'image.php'; \wp_update_image_subsizes($attachment_id); add_filter( 'qqworld-collector-disable-watermark', '__return_false' ); } public function update_featured_image_subsizes($attachment_id) { if ( !filter_var($this->options->qc_no_thumbnail_sizes_enabled, FILTER_VALIDATE_BOOLEAN) || empty($this->options->qc_no_thumbnail_sizes_featured_image_size) ) return; add_filter( 'qqworld-collector-disable-watermark', '__return_true' ); $metadata = wp_get_attachment_metadata($attachment_id); $metadata = $this->delete_subsizes($attachment_id, $metadata, $this->options->qc_no_thumbnail_sizes_featured_image_size); remove_filter( 'intermediate_image_sizes_advanced', array($this, 'normal_image_sizes') ); remove_filter( 'wp_get_missing_image_subsizes', array($this, 'normal_image_sizes') ); add_filter( 'intermediate_image_sizes_advanced', array($this, 'featured_image_sizes') ); add_filter( 'wp_get_missing_image_subsizes', array($this, 'featured_image_sizes') ); if (!function_exists('\wp_update_image_subsizes')) include ABSPATH . DIRECTORY_SEPARATOR . 'wp-admin' . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'image.php'; \wp_update_image_subsizes($attachment_id); remove_filter( 'intermediate_image_sizes_advanced', array($this, 'featured_image_sizes') ); remove_filter( 'wp_get_missing_image_subsizes', array($this, 'featured_image_sizes') ); add_filter( 'intermediate_image_sizes_advanced', array($this, 'normal_image_sizes') ); add_filter( 'wp_get_missing_image_subsizes', array($this, 'normal_image_sizes') ); add_filter( 'qqworld-collector-disable-watermark', '__return_false' ); } public function delete_subsizes($attachment_id, $metadata, $disabled_sizes) { $fullsize_path = get_attached_file($attachment_id); $dirname = dirname($fullsize_path); $deleted = false; foreach ($metadata['sizes'] as $size => $args) { if (in_array($size, $disabled_sizes)) { $deleted = true; unset($metadata['sizes'][$size]); $filepath = $dirname . DIRECTORY_SEPARATOR . $args['file']; if (file_exists($filepath)) unlink($filepath); do_action( 'qqworld-collector-cloud-storage-delete-thumbnail-size', $attachment_id, $metadata['file'], $args ); } } if ($deleted) wp_update_attachment_metadata($attachment_id, $metadata); return $metadata; } public function add_bulk_actions($actions) { $actions['update-subsizes'] = __('Update Subsizes', $this->text_domain); return $actions; } public function handle_bulk_actions( $redirect_to, $doaction, $post_ids ) { switch ($doaction) { case 'update-subsizes': foreach ( $post_ids as $attachment_id ) { $this->handle_attachment($attachment_id); } $redirect_to = add_query_arg( 'bulk_update_subsizes', count( $post_ids ), $redirect_to ); break; } return $redirect_to; } public function handle_attachment($attachment_id, $only_featured = false) { global $wpdb; $sql = $wpdb->prepare("SELECT `meta_id` FROM `{$wpdb->postmeta}` WHERE `meta_key` = '_thumbnail_id' AND `meta_value` = %d LIMIT 1", $attachment_id); $result = $wpdb->get_row($sql); if ($result) { $this->update_featured_image_subsizes($attachment_id); } elseif (!$only_featured) { $this->update_normal_image_subsizes($attachment_id); } } public function admin_notices() { if ( ! empty( $_REQUEST['bulk_update_subsizes'] ) ) { $hanler_count = intval( $_REQUEST['bulk_update_subsizes'] ); printf( '<div id="message" class="updated fade"><p>' . _n( 'Updated the subsizes of 1 attachment.', 'Updated the subsizes of %d attachments.', $hanler_count, $this->text_domain) . '</p></div>', $hanler_count ); } } public function scanning() { if (!isset($_POST['mode']) || empty($_POST['mode'])) die(); extract($_POST); $exclude = get_option('qqworld-collector-no-thumbnail-sizes-'.$mode.'-images-exclude', array()); $exclude = $exclude ? $exclude : array(); for ($paged=0; $paged<=99999; $paged++) { $args = array( 'post_type' => 'attachment', 'post_status' => 'any', 'post_mime_type' => 'image', 'posts_per_page' => 100, 'offset' => 100*$paged, 'exclude' => $exclude ); $posts = get_posts($args); if (!empty($posts)) { foreach ($posts as $post) { switch ($mode) { case 'featured': $this->handle_attachment($post->ID, true); break; case 'all': default: $this->handle_attachment($post->ID); break; } $exclude[] = $post->ID; } update_option('qqworld-collector-no-thumbnail-sizes-'.$mode.'-images-exclude', $exclude); } else { break; } } $results = array( 'success' => true ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function restart_scanning() { if (!isset($_POST['mode']) || empty($_POST['mode'])) die(); extract($_POST); update_option('qqworld-collector-no-thumbnail-sizes-'.$mode.'-images-exclude', array()); $results = array( 'success' => true ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } } ?>